import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.util.*;import java.util.stream.*;
public class Study {
private static void create(Path out)throws IOException {File parent=out.toAbsolutePath().getParent().toFile();if(!parent.exists()&&!parent.mkdirs())throw new IOException("Не создан каталог "+parent);File f=out.toFile();if(!f.exists()&&!f.createNewFile())throw new IOException("Не создан файл "+f);}
public static void process(Path in,Path out)throws IOException{if(Files.exists(out)&&Files.isSameFile(in,out))throw new IOException("Вход и выход — один файл");create(out);Files.newBufferedWriter(out,StandardCharsets.UTF_8).close();var lines=Files.readAllLines(in,StandardCharsets.UTF_8);int n=lines.size();int[][] matrix=new int[n][n],transposed=new int[n][n];for(int i=0;i<n;i++){String[] values=lines.get(i).strip().split("\\s+");if(values.length!=n)throw new IOException("Не квадратная матрица");for(int j=0;j<n;j++)matrix[i][j]=Integer.parseInt(values[j]);}for(int i=0;i<n;i++)for(int j=0;j<n;j++)transposed[j][i]=matrix[i][j];var result=new ArrayList<String>();result.add("# Исходная");for(int[] row:matrix)result.add(Arrays.stream(row).mapToObj(Integer::toString).collect(Collectors.joining(" ")));result.add("# Транспонированная");for(int[] row:transposed)result.add(Arrays.stream(row).mapToObj(Integer::toString).collect(Collectors.joining(" ")));create(out);Files.write(out,result,StandardCharsets.UTF_8);}
}
